function PouringLadleLiningCementMaker.init() PouringLadleLiningCementMaker.ironStock=12; PouringLadleLiningCementMaker.bronzeStock=10; PouringLadleLiningCementMaker.woodStock=14; PouringLadleLiningCementMaker.leatherStock=8; PouringLadleLiningCementMaker.silverStock=8; PouringLadleLiningCementMaker.goldStock=6; PouringLadleLiningCementMaker.jewelStock=4; PouringLadleLiningCementMaker.pearlStock=4; PouringLadleLiningCementMaker.productStock={}; PouringLadleLiningCementMaker.buildings={}; PouringLadleLiningCementMaker.maker=nil; PouringLadleLiningCementMaker.activeMaking={}; PouringLadleLiningCementMaker.totalProducts=0; PouringLadleLiningCementMaker.dayTimer=0; print("[PouringLadleLiningCementMaker] Royal Pouring Ladle Lining Cement Maker System initialized (6 products, 4 buildings)") end
function PouringLadleLiningCementMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PouringLadleLiningCementMaker.maker={name=n or ("Cementar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Cementar najet: %s (spretnost: %d)",PouringLadleLiningCementMaker.maker.name,s),"success") end; return true end
function PouringLadleLiningCementMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PouringLadleLiningCementMaker.build(id) local ok,e=PouringLadleLiningCementMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PouringLadleLiningCementMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PouringLadleLiningCementMaker.getQualityBonus() local b=0; for _,bd in ipairs(PouringLadleLiningCementMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PouringLadleLiningCementMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PouringLadleLiningCementMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PouringLadleLiningCementMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PouringLadleLiningCementMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PouringLadleLiningCementMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PouringLadleLiningCementMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PouringLadleLiningCementMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PouringLadleLiningCementMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PouringLadleLiningCementMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PouringLadleLiningCementMaker.buildings==0 then return false,"Potrebna cementna delavnica" end; if not PouringLadleLiningCementMaker.maker then return false,"Potreben cementar" end; return true end
function PouringLadleLiningCementMaker.make(pt,qty) qty=qty or 1; local ok,e=PouringLadleLiningCementMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PouringLadleLiningCementMaker.ironStock=PouringLadleLiningCementMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PouringLadleLiningCementMaker.bronzeStock=PouringLadleLiningCementMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PouringLadleLiningCementMaker.woodStock=PouringLadleLiningCementMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PouringLadleLiningCementMaker.leatherStock=PouringLadleLiningCementMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PouringLadleLiningCementMaker.silverStock=PouringLadleLiningCementMaker.silverStock-d.silverCost*qty end; if d.goldCost then PouringLadleLiningCementMaker.goldStock=PouringLadleLiningCementMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PouringLadleLiningCementMaker.jewelStock=PouringLadleLiningCementMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PouringLadleLiningCementMaker.pearlStock=PouringLadleLiningCementMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PouringLadleLiningCementMaker.maker then t=math.max(1,t-math.floor(PouringLadleLiningCementMaker.maker.skill/13)) end; table.insert(PouringLadleLiningCementMaker.activeMaking,{id="pouringladleliningcement_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PouringLadleLiningCementMaker.completeMaking(m) local q=1.0+(PouringLadleLiningCementMaker.getQualityBonus()/100); if PouringLadleLiningCementMaker.maker then q=q+(PouringLadleLiningCementMaker.maker.skill/140) end; q=math.min(2.5,q); PouringLadleLiningCementMaker.productStock[m.productType]=(PouringLadleLiningCementMaker.productStock[m.productType] or 0)+m.quantity; PouringLadleLiningCementMaker.totalProducts=PouringLadleLiningCementMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PouringLadleLiningCementMaker.maker then PouringLadleLiningCementMaker.maker.itemsMade=PouringLadleLiningCementMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PouringLadleLiningCementMaker.maker.skill=math.min(100,PouringLadleLiningCementMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Cement izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pouringladleliningcement.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PouringLadleLiningCementMaker.update(dt) if not _G.state then return end; PouringLadleLiningCementMaker.dayTimer=PouringLadleLiningCementMaker.dayTimer+dt; if PouringLadleLiningCementMaker.dayTimer>=30 then PouringLadleLiningCementMaker.dayTimer=0; for i=#PouringLadleLiningCementMaker.activeMaking,1,-1 do local m=PouringLadleLiningCementMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PouringLadleLiningCementMaker.completeMaking(m); table.remove(PouringLadleLiningCementMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PouringLadleLiningCementMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PouringLadleLiningCementMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
